#!/usr/bin/env node
// scripts/stale-milestone-rank.mjs
//
// Ranks stale milestones (pending > 0 AND lastShipped older than --stale-days
// OR never started) by archive priority.
//
// Closes audit findings F2 + F3 from AUDIT-DEV-TOOLS-PIPELINES-2026-05-16:
//   F2: 394 stale milestones drown 14 active (28.14x search-space noise)
//   F3: 5/6 META-audit scripts missing — this is one of them
//
// Source of truth: state/shared/MILESTONE_PROGRESS.json (auto-regenerated by
// scripts/build-milestone-progress.mjs). Stale rule mirrors BUILD_STATE's
// STALE_MILESTONES classifier: pending > 0 AND (lastShippedDate is null OR
// older than threshold_days).
//
// Usage:
//   node scripts/stale-milestone-rank.mjs                 # text dashboard, top 25
//   node scripts/stale-milestone-rank.mjs --json          # full machine-readable
//   node scripts/stale-milestone-rank.mjs --top 10        # top-N override
//   node scripts/stale-milestone-rank.mjs --stale-days 60 # threshold override
//   node scripts/stale-milestone-rank.mjs --archive-candidates  # only never_started + age>=180d
//   node scripts/stale-milestone-rank.mjs --frozen-time ISO     # deterministic for tests
//
// Exit codes:
//   0 — measurement OK (regardless of count)
//   2 — input file missing / corrupt
//
// Determinism: with --frozen-time set, output is byte-stable for the same
// MILESTONE_PROGRESS.json snapshot. Stable sort: primary by score DESC, tie-
// breaker by milestone id ASC.

import { readFileSync, existsSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(__dirname, "..");
const PROGRESS_PATH = resolve(REPO_ROOT, "state/shared/MILESTONE_PROGRESS.json");

const DEFAULT_STALE_DAYS = 30;
const DEFAULT_ARCHIVE_AGE_DAYS = 180;
const DEFAULT_TOP_N = 25;
const MS_PER_DAY = 86_400_000;

// ─────────────────────────────────────────────────────────────────────────────
// CLI parsing — small, no deps. Unknown flag → exit 2 with a clear message.
// ─────────────────────────────────────────────────────────────────────────────
function parseArgs(argv) {
  const out = {
    json: false,
    archiveCandidates: false,
    topN: DEFAULT_TOP_N,
    staleDays: DEFAULT_STALE_DAYS,
    archiveAgeDays: DEFAULT_ARCHIVE_AGE_DAYS,
    frozenTime: process.env.PRISM_AUDIT_FROZEN_TIME || null,
    progressPath: PROGRESS_PATH,
  };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--json") out.json = true;
    else if (a === "--archive-candidates") out.archiveCandidates = true;
    else if (a === "--top") { out.topN = readIntArg(argv[++i], "--top", 1, 1000); }
    else if (a === "--stale-days") { out.staleDays = readIntArg(argv[++i], "--stale-days", 1, 3650); }
    else if (a === "--archive-age-days") { out.archiveAgeDays = readIntArg(argv[++i], "--archive-age-days", 1, 3650); }
    else if (a === "--frozen-time") { out.frozenTime = argv[++i]; }
    else if (a === "--progress-path") { out.progressPath = resolve(argv[++i]); }
    else if (a === "--help" || a === "-h") { printHelp(); process.exit(0); }
    else { console.error(`unknown flag: ${a}`); process.exit(2); }
  }
  return out;
}

function readIntArg(raw, name, min, max) {
  const n = Number(raw);
  if (!Number.isFinite(n) || !Number.isInteger(n) || n < min || n > max) {
    console.error(`${name} requires integer in [${min},${max}], got: ${raw}`);
    process.exit(2);
  }
  return n;
}

function printHelp() {
  // Stay aligned with the top-of-file usage block — single source.
  console.log(`stale-milestone-rank.mjs — rank stale milestones by archive priority

Reads state/shared/MILESTONE_PROGRESS.json.
Stale: pending > 0 AND (lastShippedDate is null OR older than --stale-days).

Flags:
  --json                  emit JSON to stdout (instead of text dashboard)
  --top N                 keep top-N (default ${DEFAULT_TOP_N})
  --stale-days N          stale threshold in days (default ${DEFAULT_STALE_DAYS})
  --archive-candidates    keep only never_started + age >= --archive-age-days
  --archive-age-days N    archive-candidate age (default ${DEFAULT_ARCHIVE_AGE_DAYS})
  --frozen-time ISO       deterministic "now" for tests (also: PRISM_AUDIT_FROZEN_TIME)
  --progress-path PATH    override MILESTONE_PROGRESS.json location

Exit: 0 ok, 2 input missing/corrupt/bad-flag.`);
}

// ─────────────────────────────────────────────────────────────────────────────
// Core ranking — pure function. No I/O. Easy to test.
// Score: composite of pending-unit weight + age-in-days + never-started bonus.
// ─────────────────────────────────────────────────────────────────────────────
export function classifyStale(milestone, nowMs, staleDays) {
  const pending = Number(milestone.pending) || 0;
  if (pending <= 0) return null;
  const ageMs = ageOf(milestone.lastShippedDate, nowMs);
  // Treat null, undefined, "", and unparseable date strings all as "never started".
  // MILESTONE_PROGRESS.json emits "" (not null) for never-shipped milestones —
  // strict null-check would mis-classify them as stale_progress with age=null.
  const lsdRaw = milestone.lastShippedDate;
  const isNeverStarted = lsdRaw == null || lsdRaw === "" || ageMs == null;
  const ageDays = ageMs == null ? null : Math.floor(ageMs / MS_PER_DAY);
  // Stale = never started OR older than threshold.
  if (!isNeverStarted && ageDays != null && ageDays < staleDays) return null;
  // Score: pending units (linear) + age days (linear) + 365-day "never started" bonus
  // so unstarted milestones outrank low-pending old ones, but a high-pending
  // recently-shipped milestone still ranks above an unstarted low-pending one.
  const ageBucket = ageDays == null ? 365 : ageDays;
  const neverStartedBonus = isNeverStarted ? 365 : 0;
  const score = pending * 2 + ageBucket + neverStartedBonus;
  return {
    id: String(milestone.id ?? ""),
    title: String(milestone.title ?? ""),
    track: String(milestone.track ?? ""),
    pending,
    shipped: Number(milestone.shipped) || 0,
    total: Number(milestone.total) || 0,
    lastShippedDate: milestone.lastShippedDate ?? null,
    age_days: ageDays,
    never_started: isNeverStarted,
    claimed_status: milestone.claimedStatus ?? null,
    derived_status: milestone.derivedStatus ?? null,
    drift: Boolean(milestone.drift),
    score,
    archive_candidate: isNeverStarted && (ageDays == null || ageDays >= 365),
    reason: isNeverStarted ? "never_started" : "stale_progress",
  };
}

function ageOf(iso, nowMs) {
  if (iso == null) return null;
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return null;
  const age = nowMs - t;
  return age < 0 ? 0 : age;
}

export function rankStale(milestones, opts) {
  const { nowMs, staleDays, archiveCandidates, archiveAgeDays } = opts;
  const out = [];
  for (const m of milestones) {
    const row = classifyStale(m, nowMs, staleDays);
    if (!row) continue;
    if (archiveCandidates) {
      const isAged = row.age_days == null || row.age_days >= archiveAgeDays;
      if (!(row.never_started && isAged)) continue;
    }
    out.push(row);
  }
  // Stable sort: score DESC, then id ASC
  out.sort((a, b) => (b.score - a.score) || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  return out;
}

// ─────────────────────────────────────────────────────────────────────────────
// Renderers
// ─────────────────────────────────────────────────────────────────────────────
function renderText(ranked, opts, totalStale, generatedAt) {
  const lines = [];
  lines.push("─── Stale Milestone Ranking ───");
  lines.push(`Source: state/shared/MILESTONE_PROGRESS.json (generated ${generatedAt})`);
  lines.push(`Stale threshold: ${opts.staleDays}d  ·  Total stale: ${totalStale}  ·  Showing top ${Math.min(opts.topN, ranked.length)}`);
  if (opts.archiveCandidates) {
    lines.push(`Filter: --archive-candidates (never_started AND age >= ${opts.archiveAgeDays}d)`);
  }
  lines.push("");
  if (ranked.length === 0) {
    lines.push("(no stale milestones matched the filter)");
    return lines.join("\n");
  }
  const top = ranked.slice(0, opts.topN);
  // Compact aligned table
  const idW = Math.min(36, Math.max(...top.map((r) => r.id.length), 2));
  lines.push(pad("ID", idW) + "  pend  age   reason          drift");
  lines.push(pad("─".repeat(idW), idW) + "  ────  ────  ──────────────  ─────");
  for (const r of top) {
    const age = r.age_days == null ? "  ∅ " : String(r.age_days).padStart(4);
    lines.push(
      pad(r.id, idW) +
        "  " + String(r.pending).padStart(4) +
        "  " + age +
        "  " + r.reason.padEnd(14) +
        "  " + (r.drift ? "yes" : "no"),
    );
  }
  if (ranked.length > opts.topN) {
    lines.push("");
    lines.push(`(+ ${ranked.length - opts.topN} more — use --top ${ranked.length} for full list)`);
  }
  return lines.join("\n");
}

function pad(s, w) {
  if (s.length >= w) return s.slice(0, w);
  return s + " ".repeat(w - s.length);
}

// ─────────────────────────────────────────────────────────────────────────────
// I/O wrapper
// ─────────────────────────────────────────────────────────────────────────────
function loadProgress(progressPath) {
  if (!existsSync(progressPath)) {
    console.error(`MILESTONE_PROGRESS.json not found at: ${progressPath}`);
    process.exit(2);
  }
  let raw;
  try {
    raw = readFileSync(progressPath, "utf8");
  } catch (err) {
    console.error(`read failed: ${err instanceof Error ? err.message : String(err)}`);
    process.exit(2);
  }
  try {
    const j = JSON.parse(raw);
    if (!j || !Array.isArray(j.milestones)) {
      console.error(`MILESTONE_PROGRESS.json has no .milestones[] array`);
      process.exit(2);
    }
    return j;
  } catch (err) {
    console.error(`JSON parse failed: ${err instanceof Error ? err.message : String(err)}`);
    process.exit(2);
  }
}

function resolveNowMs(frozenTime) {
  if (!frozenTime) return Date.now();
  const t = Date.parse(frozenTime);
  if (!Number.isFinite(t)) {
    console.error(`--frozen-time invalid ISO: ${frozenTime}`);
    process.exit(2);
  }
  return t;
}

// ─────────────────────────────────────────────────────────────────────────────
// Main — only fires when this file is the CLI entry-point.
// Pure functions above are exported for tests.
// ─────────────────────────────────────────────────────────────────────────────
function isMain() {
  const entry = process.argv[1] ? resolve(process.argv[1]) : "";
  return entry === fileURLToPath(import.meta.url);
}

if (isMain()) {
  const opts = parseArgs(process.argv.slice(2));
  const data = loadProgress(opts.progressPath);
  const nowMs = resolveNowMs(opts.frozenTime);
  const ranked = rankStale(data.milestones, {
    nowMs,
    staleDays: opts.staleDays,
    archiveCandidates: opts.archiveCandidates,
    archiveAgeDays: opts.archiveAgeDays,
  });
  if (opts.json) {
    const payload = {
      schemaVersion: 1,
      generatedAt: new Date(nowMs).toISOString(),
      source: opts.progressPath,
      sourceGeneratedAt: data.generatedAt ?? null,
      thresholds: { stale_days: opts.staleDays, archive_age_days: opts.archiveAgeDays },
      filter: { archive_candidates_only: opts.archiveCandidates, top_n: opts.topN },
      totals: { total_milestones: data.milestones.length, total_stale: ranked.length },
      ranked: ranked.slice(0, opts.topN),
    };
    process.stdout.write(JSON.stringify(payload, null, 2) + "\n");
  } else {
    process.stdout.write(renderText(ranked, opts, ranked.length, data.generatedAt ?? "?") + "\n");
  }
  process.exit(0);
}
